{
  "designUI": "aceaff7ef9d2138e",
  "id": "capture",
  "version": "0.20.0",
  "name": "name",
  "summary": "summary",
  "author": "Meso",
  "minMeso": "0.3.0",
  "platforms": [
    "macos"
  ],
  "run": {
    "macos": "macos/MesoCapture"
  },
  "switch": "on",
  "stays": true,
  "permissions": {
    "windows": true,
    "screen": true,
    "writes": [
      "setting:saveFolder"
    ],
    "services": [
      "recognize"
    ],
    "microphone": true,
    "systemAudio": true,
    "camera": true,
    "keystrokes": true
  },
  "provides": {
    "settings": {
      "on": {
        "type": "toggle",
        "title": "on",
        "summary": "onSummary",
        "default": true
      },
      "copies": {
        "type": "toggle",
        "title": "copies",
        "default": true
      },
      "saves": {
        "type": "toggle",
        "title": "saves",
        "default": false
      },
      "saveFolder": {
        "type": "folder",
        "title": "saveFolder",
        "default": "~/Desktop"
      },
      "cards": {
        "type": "toggle",
        "title": "cards",
        "summary": "cardsSummary",
        "default": true
      },
      "cardCorner": {
        "type": "choice",
        "title": "cardCorner",
        "default": "bottomLeft",
        "order": [
          "bottomLeft",
          "bottomRight",
          "topLeft",
          "topRight"
        ],
        "choices": {
          "bottomLeft": {
            "title": "cornerBottomLeft"
          },
          "bottomRight": {
            "title": "cornerBottomRight"
          },
          "topLeft": {
            "title": "cornerTopLeft"
          },
          "topRight": {
            "title": "cornerTopRight"
          }
        }
      },
      "format": {
        "type": "choice",
        "title": "format",
        "default": "png",
        "order": [
          "png",
          "jpeg"
        ],
        "choices": {
          "png": {
            "title": "png"
          },
          "jpeg": {
            "title": "jpeg"
          }
        }
      },
      "loupe": {
        "type": "toggle",
        "title": "loupe",
        "summary": "loupeSummary",
        "default": false
      },
      "freezeScreen": {
        "type": "toggle",
        "title": "freezeScreen",
        "summary": "freezeScreenSummary",
        "default": false
      },
      "colorFormat": {
        "type": "choice",
        "title": "colorFormat",
        "default": "hex",
        "order": [
          "hex",
          "rgb"
        ],
        "choices": {
          "hex": {
            "title": "hex"
          },
          "rgb": {
            "title": "rgb"
          }
        }
      },
      "recordingBar": {
        "type": "toggle",
        "title": "recordingBar",
        "summary": "recordingBarSummary",
        "section": "sectionRecording",
        "default": true
      },
      "barsInRecording": {
        "type": "toggle",
        "title": "barsInRecording",
        "summary": "barsInRecordingSummary",
        "default": false
      },
      "recordingDim": {
        "type": "toggle",
        "title": "recordingDim",
        "section": "sectionRecording",
        "default": true
      },
      "recordingFocus": {
        "type": "toggle",
        "title": "recordingFocus",
        "summary": "recordingFocusSummary",
        "section": "sectionRecording",
        "default": false
      },
      "soundTracks": {
        "type": "choice",
        "title": "soundTracks",
        "summary": "soundTracksSummary",
        "section": "sectionRecording",
        "default": "mixed",
        "order": [
          "mixed",
          "separate"
        ],
        "choices": {
          "mixed": {
            "title": "soundMixed"
          },
          "separate": {
            "title": "soundSeparate"
          }
        }
      },
      "soundMono": {
        "type": "toggle",
        "title": "soundMono",
        "section": "sectionRecording",
        "default": false
      },
      "keystrokes": {
        "type": "choice",
        "title": "keystrokes",
        "summary": "keystrokesSummary",
        "section": "sectionRecording",
        "default": "shortcuts",
        "order": [
          "shortcuts",
          "all"
        ],
        "choices": {
          "shortcuts": {
            "title": "keysShortcuts"
          },
          "all": {
            "title": "keysAll"
          }
        }
      },
      "clickStyle": {
        "type": "choice",
        "title": "clickStyle",
        "section": "sectionRecording",
        "default": "ring",
        "order": [
          "ring",
          "ripple"
        ],
        "choices": {
          "ring": {
            "title": "clickRing"
          },
          "ripple": {
            "title": "clickRipple"
          }
        }
      },
      "clickColor": {
        "type": "choice",
        "title": "clickColor",
        "section": "sectionRecording",
        "default": "white",
        "order": [
          "white",
          "yellow",
          "red",
          "green",
          "blue",
          "purple"
        ],
        "choices": {
          "white": {
            "title": "colorWhite"
          },
          "yellow": {
            "title": "colorYellow"
          },
          "red": {
            "title": "colorRed"
          },
          "green": {
            "title": "colorGreen"
          },
          "blue": {
            "title": "colorBlue"
          },
          "purple": {
            "title": "colorPurple"
