        "title": "gifFrameRate",
        "section": "sectionRecording",
        "default": "fps15",
        "order": [
          "fps10",
          "fps15",
          "fps20",
          "fps30"
        ],
        "choices": {
          "fps10": {
            "title": "fps10"
          },
          "fps15": {
            "title": "fps15"
          },
          "fps20": {
            "title": "fps20"
          },
          "fps30": {
            "title": "fps30"
          }
        }
      },
      "gifWidth": {
        "type": "choice",
        "title": "gifWidth",
        "summary": "gifWidthSummary",
        "section": "sectionRecording",
        "default": "px800",
        "order": [
          "original",
          "px1280",
          "px960",
          "px800",
          "px640",
          "px480"
        ],
        "choices": {
