            "title": "gifOriginal"
          },
          "px1280": {
            "title": "px1280"
          },
          "px960": {
            "title": "px960"
          },
          "px800": {
            "title": "px800"
          },
          "px640": {
            "title": "px640"
          },
          "px480": {
            "title": "px480"
          }
        }
      },
      "oneX": {
        "type": "toggle",
        "title": "oneX",
        "summary": "oneXSummary",
        "default": false
      },
      "naming": {
        "type": "choice",
        "title": "naming",
        "default": "standard",
        "order": [
          "standard",
          "dateOnly",
          "stamp"
        ],
        "choices": {
          "standard": {
            "title": "namingStandard"
          },
          "dateOnly": {
            "title": "namingDateOnly"
          },
          "stamp": {
            "title": "namingStamp"
          }
        }
      },
      "jpegQuality": {
        "type": "choice",
        "title": "jpegQuality",
        "default": "high",
        "order": [
          "high",
          "medium",
          "low"
        ],
        "choices": {
          "high": {
            "title": "qualityHigh"
          },
          "medium": {
            "title": "qualityMedium"
          },
          "low": {
            "title": "qualityLow"
          }
        }
      },
      "hideIcons": {
        "type": "toggle",
        "title": "hideIcons",
        "summary": "hideIconsSummary",
        "default": false
      },
      "timerSeconds": {
        "type": "choice",
        "title": "timerSeconds",
        "default": "s5",
        "order": [
          "s3",
          "s5",
          "s10"
        ],
        "choices": {
          "s3": {
            "title": "seconds3"
          },
          "s5": {
            "title": "seconds5"
          },
          "s10": {
            "title": "seconds10"
          }
        }
      },
      "windowShadow": {
        "type": "toggle",
        "title": "windowShadow",
        "summary": "windowShadowSummary",
        "section": "sectionWindow",
        "default": true
      },
      "windowBackground": {
        "type": "choice",
        "title": "windowBackground",
        "section": "sectionWindow",
        "default": "none",
        "order": [
          "none",
          "white",
          "black",
          "wallpaper"
        ],
        "choices": {
          "none": {
            "title": "backgroundNone"
          },
          "white": {
            "title": "backgroundWhite"
          },
          "black": {
            "title": "backgroundBlack"
          },
          "wallpaper": {
            "title": "backgroundWallpaper"
          }
        }
      },
      "keepHistory": {
        "type": "toggle",
        "title": "keepHistory",
        "summary": "keepHistorySummary",
        "section": "sectionHistory",
        "default": true
      }
    },
    "settingsOrder": [
      "on",
      "copies",
      "saves",
      "saveFolder",
      "format",
      "loupe",
      "freezeScreen",
      "colorFormat",
      "jpegQuality",
      "oneX",
