files.manifest.json:
{
  "id": "downloader",
  "version": "0.5.2",
  "name": "name",
  "summary": "summary",
  "author": "Meso",
  "minMeso": "0.1.0",
  "platforms": [
    "macos"
  ],
  "stays": true,
  "run": {
    "macos": "macos/MesoDownloader"
  },
  "switch": "on",
  "permissions": {
    "network": true,
    "sessions": true,
    "writes": [
      "setting:saveFolder"
    ]
  },
  "sync": {
    "title": "syncTitle",
    "detail": "syncDetail",
    "icon": "download",
    "records": true
  },
  "provides": {
    "settings": {
      "on": {
        "type": "toggle",
        "title": "on",
        "default": true,
        "summary": "onSummary"
      },
      "saveFolder": {
        "type": "folder",
        "default": "~/Downloads",
        "title": "saveFolder"
      },
      "kind": {
        "type": "choice",
        "default": "video",
        "title": "kind",
        "order": [
          "video",
          "audio",
          "file"
        ],
        "choices": {
          "video": {
            "title": "video",
            "ignores": ["audioFormat"]
          },
          "audio": {
            "title": "audio",
            "ignores": [
              "quality",
              "compatible",
              "subtitles"
            ]
          },
          "file": {
            "title": "file",
            "ignores": [
              "quality",
              "audioFormat",
              "compatible",
              "subtitles"
            ]
          }
        }
      },
      "quality": {
        "type": "choice",
        "default": "best",
        "title": "quality",
        "order": [
          "best",
          "upTo2160",
          "upTo1080",
          "upTo720"
        ],
        "choices": {
          "best": {
            "title": "qualityBest"
          },
          "upTo2160": {
            "title": "quality2160",
            "short": "quality2160Short"
          },
          "upTo1080": {
            "title": "quality1080",
            "short": "quality1080Short"
          },
          "upTo720": {
            "title": "quality720",
            "short": "quality720Short"
          }
        }
      },
      "audioFormat": {
        "type": "choice",
        "default": "m4a",
        "title": "audioFormat",
        "order": ["m4a", "mp3", "original"],
        "choices": {
          "m4a": {"title": "audioM4A"},
          "mp3": {"title": "audioMP3"},
          "original": {"title": "audioOriginal", "summary": "audioOriginalSummary"}
        }
      },
      "compatible": {
        "type": "toggle",
        "default": true,
        "title": "compatible",
        "summary": "compatibleSummary"
      },
      "subtitles": {
        "type": "choice",
        "default": "off",
        "title": "subtitles",
        "order": [
          "off",
          "yours",
          "yoursAuto"
        ],
        "choices": {
          "off": {
            "title": "subtitlesOff"
          },
          "yours": {
            "title": "subtitlesYours"
          },
          "yoursAuto": {
            "title": "subtitlesYoursAuto"
          }
        }
      },
      "whenDone": {
        "type": "choice",
        "default": "nothing",
        "title": "whenDone",
        "order": [
          "nothing",
          "reveal",
          "open"
        ],
        "choices": {
          "nothing": {
            "title": "whenDoneNothing"
          },
          "reveal": {
            "title": "whenDoneReveal"
          },
          "open": {
            "title": "whenDoneOpen"
          }
        }
      },
      "atOnce": {
        "type": "number",
        "default": 2,
        "min": 1,
        "max": 4,
        "title": "atOnce"
      },
      "updateDaily": {
        "type": "toggle",
        "default": true,
        "title": "updateDaily",
        "summary": "updateDailySummary"
      }
    },
    "settingsOrder": [
      "on",
      "saveFolder",
      "kind",
      "quality",
      "audioFormat",
      "compatible",
      "subtitles",
      "whenDone",
      "atOnce",
      "updateDaily"
    ],
    "actions": {
      "download": {
        "title": "downloadFrontTab",
        "summary": "downloadSummary",
        "effects": "external",
        "output": "text",
        "reads": "tab",
        "args": [
          {
            "name": "url",
            "type": "string",
            "required": true,
            "default": {
              "from": "text"
            }
          },
          {
            "name": "kind",
            "type": "string"
          }
        ],
        "icon": "download"
      },
      "downloadClipboard": {
        "title": "downloadClipboard",
        "summary": "downloadSummary",
        "effects": "external",
        "output": "text",
        "reads": "clipboard",
        "args": [
          {
            "name": "url",
            "type": "string",
            "required": true,
            "default": {
              "from": "text"
            }
          },
          {
            "name": "kind",
            "type": "string"
          }
        ],
        "icon": "clipboard"
      },
      "downloadAudio": {
        "title": "downloadAudio",
        "summary": "downloadSummary",
        "effects": "external",
        "output": "text",
        "reads": "tab",
        "args": [
          {
            "name": "url",
            "type": "string",
            "required": true,
            "default": {
              "from": "text"
            }
          }
        ],
        "icon": "music"
      },
      "downloadNew": {
        "title": "downloadNew",
        "summary": "downloadNewSummary",
        "effects": "external",
        "output": "text",
        "reads": "tab",
        "args": [
          {
            "name": "url",
            "type": "string",
            "required": true,
            "default": {
              "from": "text"
            }
          },
          {
            "name": "kind",
            "type": "string"
          }
        ],
        "icon": "add"
      }
    },
    "tools": [
      {
        "id": "yt-dlp",
        "settings": [
          "updateDaily"
        ]
      },
      {
        "id": "ffmpeg"
      },
      {
        "id": "deno"
      }
    ],
    "pages": {
      "downloads": {
        "title": "downloads",
        "jobs": {
          "link": true,
          "timeRange": true,
          "choices": [
            "kind",
            "quality",
            "audioFormat"
          ],
          "settings": [
            "saveFolder",
            "compatible",
            "subtitles",
            "whenDone",
            "atOnce"
          ]
        }
      }
    }
  }
}

